#pragma once
#include <cstdio>
#include <fstream>
#include <sstream>
#include <string>
#include <unordered_map>
#include <set>
#include <vector>
#include <algorithm>
#include <stdexcept>
#include <charconv>
#include <cctype>

namespace detail {
    inline bool is_space(char c) { return std::isspace(static_cast<unsigned char>(c)); }

    inline std::string trim(const std::string& s) {
        auto start = s.begin();
        while (start != s.end() && is_space(*start)) ++start;
        auto end = s.end();
        do { --end; } while (std::distance(start, end) > 0 && is_space(*end));
        return std::string(start, end + 1);
    }

    inline size_t find_char_or_comment(const std::string& s, char c) {
        for (size_t i = 0; i < s.size(); ++i) {
            if (s[i] == ';' || s[i] == '#') return i;
            if (s[i] == c) return i;
        }
        return std::string::npos;
    }
}

class INIReader {
public:
    INIReader() = default;

    explicit INIReader(const std::string& filename) {
        if (filename.empty()) {
            _error = -1;
            return;
        }
        std::ifstream file(filename);
        if (!file.is_open()) {
            _error = -1;
            return;
        }
        std::ostringstream buffer;
        buffer << file.rdbuf();
        Parse(buffer.str());
    }

    explicit INIReader(std::FILE* file) {
        if (!file) {
            _error = -1;
            return;
        }
        std::ostringstream buffer;
        char ch; // Avoid undefined behavior with uninitialized variable
        while (fread(&ch, 1, 1, file) == 1) {
            buffer << ch;
        }
        Parse(buffer.str());
    }

    int ParseError() const {
        switch (_error) {
            case 0: return 0;
            case -1: throw std::runtime_error("ini file not found.");
            case -2: throw std::runtime_error("memory alloc error");
            default: throw std::runtime_error("parse error on line no: " + std::to_string(_error));
        }
    }

    std::set<std::string> Sections() const {
        std::set<std::string> result;
        for (const auto& section : _values) {
            result.insert(section.first);
        }
        return result;
    }

    std::set<std::string> Keys(const std::string& section) const {
        const auto& sec = GetSection(section);
        std::set<std::string> result;
        for (const auto& kv : sec) {
            result.insert(kv.first);
        }
        return result;
    }

    std::unordered_map<std::string, std::string> Get(const std::string& section) const {
        return _values.at(section);
    }

    template <typename T = std::string>
    T Get(const std::string& section, const std::string& name) const {
        const auto& sec = GetSection(section);
        const auto& value = sec.at(name);
        return Converter<T>(value);
    }

    template <typename T>
    T Get(const std::string& section, const std::string& name, T&& default_v) const {
        try {
            return Get<T>(section, name);
        } catch (const std::out_of_range&) {
            return std::forward<T>(default_v);
        }
    }

    template <typename T = std::string>
    std::vector<T> GetVector(const std::string& section, const std::string& name) const {
        const auto& sec = GetSection(section);
        const auto& value = sec.at(name);
        return Converter<std::vector<T>>(value);
    }

    template <typename T>
    std::vector<T> GetVector(const std::string& section, const std::string& name, const std::vector<T>& default_v) const {
        try {
            return GetVector<T>(section, name);
        } catch (const std::out_of_range&) {
            return default_v;
        }
    }

    template <typename T = std::string>
    void InsertEntry(const std::string& section, const std::string& name, const T& v) {
        auto& sec = _values[section];
        if (sec.find(name) != sec.end()) {
            throw std::runtime_error("duplicate key '" + name + "' in section '" + section + "'.");
        }
        sec.emplace(name, V2String(v));
    }

    template <typename T = std::string>
    void InsertEntry(const std::string& section, const std::string& name, const std::vector<T>& vs) {
        auto& sec = _values[section];
        if (sec.find(name) != sec.end()) {
            throw std::runtime_error("duplicate key '" + name + "' in section '" + section + "'.");
        }
        sec.emplace(name, Vec2String(vs));
    }

    template <typename T = std::string>
    void UpdateEntry(const std::string& section, const std::string& name, const T& v) {
        auto& sec = _values[section];
        if (sec.find(name) == sec.end()) {
            throw std::runtime_error("key '" + name + "' not found in section '" + section + "'.");
        }
        sec[name] = V2String(v);
    }

    template <typename T = std::string>
    void UpdateEntry(const std::string& section, const std::string& name, const std::vector<T>& vs) {
        auto& sec = _values[section];
        if (sec.find(name) == sec.end()) {
            throw std::runtime_error("key '" + name + "' not found in section '" + section + "'.");
        }
        sec[name] = Vec2String(vs);
    }

private:
    int _error{0};
    std::unordered_map<std::string, std::unordered_map<std::string, std::string>> _values;

    const std::unordered_map<std::string, std::string>& GetSection(const std::string& section) const {
        auto it = _values.find(section);
        if (it == _values.end()) {
            throw std::runtime_error("section '" + section + "' not found.");
        }
        return it->second;
    }

    std::string& FindEntry(const std::string& section, const std::string& name) {
        auto& sec = _values[section];
        auto it = sec.find(name);
        if (it == sec.end()) {
            throw std::runtime_error("key '" + name + "' not found in section '" + section + "'.");
        }
        return it->second;
    }

    void Parse(std::string_view content) {
        if (content.size() >= 3 && static_cast<unsigned char>(content[0]) == 0xEF && 
            static_cast<unsigned char>(content[1]) == 0xBB && static_cast<unsigned char>(content[2]) == 0xBF) {
            content = content.substr(3);
        }
        std::string current_section;
        size_t line_no{0};
        for (std::string_view line; !content.empty(); content = content.substr(line.size() + (line.back() == '\n' ? 1 : 0))) {
            ++line_no;
            size_t eol = content.find('\n');
            if (eol == std::string_view::npos) eol = content.size();
            line = content.substr(0, eol);

            // Trim and check for empty/comment
            auto trimmed = detail::trim(line);
            if (trimmed.empty() || trimmed[0] == ';' || trimmed[0] == '#') continue;

            // Check for section header
            if (trimmed.front() == '[' && trimmed.back() == ']') {
                current_section = std::string(trimmed.substr(1, trimmed.size() - 2));
                _values[current_section];
                continue;
            }

            // Parse key-value
            size_t eq_pos = detail::find_char_or_comment(trimmed, '=');
            if (eq_pos == std::string_view::npos) {
                eq_pos = detail::find_char_or_comment(trimmed, ':');
                if (eq_pos == std::string_view::npos) {
                    _error = static_cast<int>(line_no);
                    return;
                }
            }
            auto key = detail::trim(std::string(trimmed.substr(0, eq_pos)));
            auto value = detail::trim(std::string(trimmed.substr(eq_pos + 1)));
            if (key.empty()) {
                _error = static_cast<int>(line_no);
                return;
            }

            // Check for duplicate key
            if (_values[current_section].find(key) != _values[current_section].end()) {
                throw std::runtime_error("duplicate key '" + key + "' in section '" + current_section + "'.");
            }
            _values[current_section][key] = value;
        }
    }

    template <typename T>
    T Converter(const std::string& s) const {
        if constexpr (std::is_same_v<T, bool>) {
            return BoolConverter(s);
        } else if constexpr (std::is_same_v<T, std::vector<std::string>>) {
            std::vector<std::string> result;
            std::istringstream iss(s);
            std::string token;
            while (iss >> token) {
                result.push_back(token);
            }
            return result;
        } else if constexpr (std::is_same_v<T, std::vector<int>>) {
            std::vector<int> result;
            std::istringstream iss(s);
            int value; char ch;
            while (iss >> value) {
                result.push_back(value);
                if (!(iss >> ch)) break; // Stop on non-space
            }
            return result;
        } else {
            T value{};
            auto [ptr, ec] = std::from_chars(s.data(), s.data() + s.size(), value);
            if (ec != std::errc()) {
                throw std::runtime_error("cannot parse value '" + s + "' to type<T>.");
            }
            return value;
        }
    }

    bool BoolConverter(std::string s) const {
        std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c){ return std::tolower(c); });
        if (s == "1" || s == "true" || s == "yes" || s == "on") return true;
        if (s == "0" || s == "false" || s == "no" || s == "off") return false;
        throw std::runtime_error("cannot parse value '" + s + "' to bool.");
    }

    template <typename T>
    std::string V2String(const T& v) const {
        if constexpr (std::is_same_v<T, bool>) {
            return v ? "true" : "false";
        } else {
            std::ostringstream oss;
            oss << v;
            return oss.str();
        }
    }

    template <typename T>
    std::string Vec2String(const std::vector<T>& v) const {
        if (v.empty()) return "";
        std::ostringstream oss;
        for (size_t i = 0; i < v.size(); ++i) {
            if (i != 0) oss << ' ';
            oss << V2String(v[i]);
        }
        return oss.str();
    }
};
